CREATE TABLE IF NOT EXISTS brsr.review_decision_log (
    "entry_no" text NOT NULL,
    "recommendation_id" text,
    "decision" text,
    "reviewer" text,
    "decided_at" text,
    "audit_reference" text,
    "comment" text,
    "decided_at_ts" timestamptz,
    load_batch_id bigint NOT NULL REFERENCES brsr.import_batch (batch_id),
    source_path text NOT NULL,
    source_row_number integer NOT NULL,
    row_hash text NOT NULL,
    loaded_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("entry_no"),
    CONSTRAINT "review_decision_log_decision_allowed" CHECK ("decision" IS NULL OR "decision" IN ('APPROVE', 'REJECT', 'DEFER'))
);
DROP TRIGGER IF EXISTS review_decision_log_append_only ON brsr.review_decision_log;
CREATE TRIGGER review_decision_log_append_only BEFORE UPDATE OR DELETE ON brsr.review_decision_log FOR EACH ROW EXECUTE FUNCTION brsr.forbid_change();
DROP TRIGGER IF EXISTS review_decision_log_no_truncate ON brsr.review_decision_log;
CREATE TRIGGER review_decision_log_no_truncate BEFORE TRUNCATE ON brsr.review_decision_log FOR EACH STATEMENT EXECUTE FUNCTION brsr.forbid_change();

